// Компонент — функция, возвращающая JSX
function Counter() {
  const [count, setCount] = useState(0)
  return (
    <button onClick={() => setCount(count + 1)}>
      Нажато: {count}
    </button>
  )
}

// Декларативность: меняем state — React сам обновит DOM
// UI = f(state): что видно — определяется состоянием

// Композиция
function App() {
  return (
    <main>
      <Header title="App" />
      <Counter />
    </main>
  )
}

// Правильно — ref + эффект
function AutoFocus() {
  const inputRef = useRef(null)
  useEffect(() => {
    inputRef.current.focus()   // DOM-доступ ПОСЛЕ рендера
  }, [])
  return <input ref={inputRef} />
}

// НЕПРАВИЛЬНО — DOM в рендере
function Bad() {
  document.getElementById('x').focus() // узла может не быть!
  return <input id="x" />
}

// Портал — рендер в другой узел
createPortal(<Modal />, document.body)

// Опасный HTML — только доверенный/санитизированный
<div dangerouslySetInnerHTML={{__html: safe}} />

setCount(5)  // -> queue: [replace 5]
// пометка fiber, schedule рендер

// Очередь апдейтеров — последовательно:
setN(p => p+1); setN(p => p*2)
// prev=0 -> 1 -> 2 за один проход

// Lane-приоритет (упрощённо):
setUrgent(v)            // sync lane
startTransition(() => setBg(x))  // transition lane
// срочное может прервать фоновый рендер

// Результат: один render+commit на батч

function Child({user, onRename}) {
  // user.name = 'X'  // ЗАПРЕЩЕНО: мутирует объект
  // родителя для всех потребителей!

  // Правильно — попросить родителя:
  return <button onClick={() => onRename(user.id, 'X')}>
    Rename
  </button>
}

// Родитель владеет данными:
const rename = (id, name) =>
  setUsers(us => us.map(u =>
    u.id === id ? {...u, name} : u))
<Child user={u} onRename={rename}/>

