const init = {count: 0, step: 1}
function reducer(s, a) {
  switch (a.type) {
    case 'inc':  return {...s, count: s.count + s.step}
    case 'step': return {...s, step: a.value}
    case 'reset': return a.init ?? init
    default: throw new Error('unknown: ' + a.type)
  }
}

const [s, dispatch] = useReducer(reducer, init)
dispatch({type: 'inc'})
dispatch({type: 'step', value: 5})

// Передача dispatch вниз — стабилен
<Controls dispatch={dispatch} />
// ребёнок: onClick={() => dispatch({type:'inc'})}

// useFetch — инкапсуляция запроса
function useFetch(url) {
  const [data, setData] = useState(null)
  const [loading, setLoading] = useState(true)
  useEffect(() => {
    const c = new AbortController()
    setLoading(true)
    fetch(url, {signal: c.signal})
      .then(r => r.json())
      .then(d => { setData(d); setLoading(false) })
    return () => c.abort()
  }, [url])
  return { data, loading }
}

// Использование — одна строка в компоненте
const { data, loading } = useFetch('/api/users')

// Композиция хуков
function useDebounceFetch(q) {
  const dq = useDebounce(q, 300)
  return useFetch('/api?q=' + dq)
}

