  data() { return { x: 0, y: 0 } },
  mounted() { window.addEventListener('mousemove', this.track) },
  methods: { track(e) { this.x = e.clientX; this.y = e.clientY } },
  unmounted() { window.removeEventListener('mousemove', this.track) }
}
export default { mixins: [mouseMixin] }
// Откуда x, y, track? Неявно! Конфликт имён при двух миксинах

// Composable — современный способ
// useMouse.js
import { ref, onMounted, onUnmounted } from 'vue'
export function useMouse() {
  const x = ref(0), y = ref(0)
  const track = e => { x.value = e.clientX; y.value = e.clientY }
  onMounted(() => window.addEventListener('mousemove', track))
  onUnmounted(() => window.removeEventListener('mousemove', track))
  return { x, y }
}
// В компоненте — явно:
const { x, y } = useMouse()
const { x: mx, y: my } = useMouse()  // переименование — без конфликтов

// useFetch.js — типовой composable
import { ref, watch, unref } from 'vue'

export function useFetch(url) {
  const data = ref(null)
  const error = ref(null)
  const loading = ref(false)

  async function load() {
    loading.value = true
    try {
      const res = await fetch(unref(url))
      data.value = await res.json()
    } catch (e) {
      error.value = e
    } finally {
      loading.value = false
    }
  }
  watch(() => unref(url), load, { immediate: true })
  return { data, error, loading, reload: load }
}

// В компоненте
const { data, loading, reload } = useFetch(() => `/api/users/${id.value}`)

// Параметры и композиция
const { items } = usePagination(useFetch('/api/list'))

