// stores/cart.js — setup-синтаксис
export const useCartStore = defineStore('cart', () => {
  const items = ref([])
  const count = computed(() => items.value.length)
  const total = computed(() =>
    items.value.reduce((s, i) => s + i.price * i.qty, 0))

  function add(product) {
    const found = items.value.find(i => i.id === product.id)
    found ? found.qty++ : items.value.push({ ...product, qty: 1 })
  }
  async function checkout() {
    await api.checkout(items.value)
    items.value = []
  }
  return { items, count, total, add, checkout }
})

