class Vector:
    def __init__(self, x, y):
        self.x, self.y = x, y

    def __repr__(self):
        return f"Vector({self.x}, {self.y})"   # для отладки

    def __eq__(self, other):
        return (self.x, self.y) == (other.x, other.y)

    def __add__(self, other):
        return Vector(self.x + other.x, self.y + other.y)

    def __len__(self):
        return 2

v = Vector(1, 2) + Vector(3, 4)   # __add__
print(v)        # Vector(4, 6) — __str__/__repr__
v == Vector(4, 6)  # True — __eq__
len(v)          # 2 — __len__

class Animal:
    def __init__(self, name):
        self.name = name
    def speak(self):
