import functools, time

def timed(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        t0 = time.time()
        try:
            return func(*args, **kwargs)
        finally:
            print(f"{func.__name__}: {time.time()-t0:.3f}s")
    return wrapper

@timed
def heavy(): ...

# С параметром — фабрика
def retry(times):
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*a, **kw):
            for i in range(times):
                try: return func(*a, **kw)
                except Exception:
                    if i == times - 1: raise
        return wrapper
    return decorator

@retry(times=3)
def fetch(): ...

