    # Обычный метод — готовая логика для всех
    def export(self, rows) -> str:
        lines = [self.header()]
        lines += [self.format_row(r) for r in rows]
        return "\n".join(lines)

    def header(self):                       # можно переопределить
        return "---"

class CsvExporter(Exporter):
    def format_row(self, row):
        return ",".join(map(str, row))

class JsonExporter(Exporter):
    def format_row(self, row):
        import json
        return json.dumps(row)

# export() — шаблонный метод: алгоритм в базе,
# format_row — у каждого свой
print(CsvExporter().export([[1, 2], [3, 4]]))

from abc import ABC, abstractmethod

class Parser(ABC):
    @abstractmethod
    def parse(self, text: str) -> dict:
        # может иметь тело — базовое поведение
        if not text:
            raise ValueError("empty input")

class JsonParser(Parser):
    def parse(self, text):
        super().parse(text)          # используем базовую проверку
        import json
        return json.loads(text)

class BrokenParser(Parser):
    pass   # parse не реализован

BrokenParser()   # TypeError: abstract class with abstract method 'parse'

# Формальное переопределение достаточно
class Stub(Parser):
    def parse(self, text): return {}
Stub()   # ок — контракт выполнен

